<?php
declare(strict_types=1);namespace App\Interfaces\Http\Controllers\Api\V1\Certificates;
use App\Application\Certificates\CertificateService;use App\Domain\Tenancy\TenantContext;use App\Models\{CertificateTemplate,Policy,PolicyCertificate};use Illuminate\Http\{JsonResponse,Request};
final class CertificateController{public function createTemplate(Request$r,CertificateService$s):JsonResponse{$d=$r->validate(['type'=>'required|string|max:32','code'=>'required|string|max:64','layout_schema'=>'required|array','effective_from'=>'required|date','effective_until'=>'nullable|date|after_or_equal:effective_from']);return response()->json(['data'=>$s->createTemplate($d,$r->user())],201);}public function approveTemplate(Request$r,string$template,CertificateService$s):JsonResponse{return response()->json(['data'=>$s->approveTemplate(CertificateTemplate::findOrFail($template),$r->user())]);}public function receiveBatch(Request$r,CertificateService$s):JsonResponse{$d=$r->validate(['carrier_id'=>'required|uuid|exists:carriers,id','batch_number'=>'required|string|max:100','custodian_tenant_id'=>'nullable|uuid|exists:tenants,id','evidence'=>'sometimes|array','stickers'=>'required|array|min:1|max:5000','stickers.*.serial_number'=>'required|string|max:100|distinct','stickers.*.security_code'=>'required|string|min:16|max:128']);return response()->json(['data'=>$s->receiveBatch($d,$r->user())],201);}public function issue(Request$r,CertificateService$s):JsonResponse{$d=$r->validate(['policy_id'=>'required|uuid|exists:policies,id','document_type_code'=>'nullable|string|max:80','certificate_template_id'=>'nullable|uuid|exists:certificate_templates,id','serial_number'=>'required|string|max:100|unique:policy_certificates,serial_number','document_hash'=>['required','regex:/^[a-f0-9]{64}$/i'],'sticker_serial_number'=>'nullable|string']);$p=Policy::where('tenant_id',app(TenantContext::class)->id())->findOrFail($d['policy_id']);/* REQ-DUP-005: issued as an engine certificate document */return response()->json(['data'=>$s->issue($p,isset($d['certificate_template_id'])?CertificateTemplate::find($d['certificate_template_id']):null,$d,$r->user())],201);}public function verify(Request$r,CertificateService$s):JsonResponse{$d=$r->validate(['serial_number'=>'required|string|max:100','token'=>'required|string|size:64']);$c=$s->verify($d['serial_number'],$d['token'],$r->ip().'|'.$r->userAgent());return response()->json(['data'=>['verified'=>true,'serial_number'=>$c['serial_number'],'policy_number'=>$c['policy']->policy_number,'policy_status'=>$c['policy']->status,'coverage_starts_at'=>$c['policy']->coverage_starts_at,'coverage_ends_at'=>$c['policy']->coverage_ends_at,'issued_at'=>$c['issued_at'],'document_hash'=>$c['document_hash']]]);}public function void(Request$r,string$certificate,CertificateService$s):JsonResponse{$d=$r->validate(['reason'=>'required|string|min:20|max:1000']);$c=PolicyCertificate::whereHas('policy',fn($q)=>$q->where('tenant_id',app(TenantContext::class)->id()))->findOrFail($certificate);return response()->json(['data'=>$s->void($c,$d['reason'],$r->user())]);}}
